update public.exercises set consigne = '<p>C''est l''été et il fait très chaud. Vous voulez sortir avec votre fille de 8 ans. Vous choisissez une activité en fonction des critères suivants :</p><p>• dans un lieu frais, à l''abri du soleil ;<br>• accessible sans voiture ;<br>• adaptée aux enfants de son âge ;<br>• gratuite pour toute la famille.</p><p>Vous comparez ces quatre annonces. Pour chaque annonce, cochez (☒) OUI si cela correspond au critère ou NON si cela ne correspond pas.</p>', reading_text = null where id = 'lo22mvemyhx902j';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'tableau', 'Pour chaque annonce, cochez OUI ou NON.', '{"colonnes":[{"id":"lo22mvemyhx902jc1","titre":"Musée des Beaux-Arts","texte":"<p>Pour échapper à la chaleur, rien ne vaut les salles climatisées du musée des Beaux-Arts, ouvertes jusqu''à 21 h en juillet et en août. Le musée se trouve à deux pas de la station de tramway Hôtel-de-Ville, et un parc à vélos est installé devant l''entrée. Les jeunes visiteurs ne sont pas oubliés : un livret-jeu permet aux enfants de 6 à 12 ans de découvrir les tableaux en s''amusant. L''entrée est gratuite pour les moins de 18 ans ; les adultes paient 8 €. Un café avec terrasse ombragée accueille les visiteurs dans le jardin du musée.</p>"},{"id":"lo22mvemyhx902jc2","titre":"Baignade au lac de Vassy","texte":"<p>La plage du lac de Vassy est surveillée tous les jours de 11 h à 19 h. Le site n''est desservi par aucune ligne de bus : un grand parking attend les visiteurs à l''entrée. Les familles apprécieront la zone de baignade peu profonde réservée aux plus petits, ainsi que l''aire de jeux installée près du poste de secours. L''accès à la plage est libre et gratuit pour tous. Attention : la plage ne compte aucun arbre, pensez à apporter parasols et chapeaux. Les chiens ne sont pas acceptés, même tenus en laisse.</p>"},{"id":"lo22mvemyhx902jc3","titre":"Grottes du Val-Noir","texte":"<p>Envie de fraîcheur ? Aux grottes du Val-Noir, il fait 13 °C toute l''année ! Des visites guidées partent toutes les heures, de 10 h à 17 h. Pas besoin de voiture : une navette gratuite relie la gare aux grottes toutes les trente minutes. La visite dure une heure et quart et comporte plus de trois cents marches ; elle est donc interdite aux enfants de moins de 10 ans. Tarif : 9 € par adulte, 5 € pour les jeunes de 10 à 17 ans. Prévoyez un pull et des chaussures fermées : le sol est humide et glissant.</p>"},{"id":"lo22mvemyhx902jc4","titre":"Atelier d''été de la médiathèque","texte":"<p>Tous les mercredis de juillet, de 14 h à 16 h, la médiathèque des Tilleuls propose des lectures, des contes et des jeux de société pour les 6-10 ans, dans sa grande salle climatisée. Les parents peuvent rester avec leurs enfants ou profiter de ce moment pour emprunter des livres. L''atelier est gratuit, mais le nombre de places est limité : pensez à vous inscrire à l''accueil. La médiathèque est située en périphérie, loin des transports en commun ; prévoyez votre voiture, un parking gratuit est disponible. Chaque séance se termine par un goûter offert.</p>"}],"criteres":[{"id":"lo22mvemyhx902jt1","texte":"Fraîcheur"},{"id":"lo22mvemyhx902jt2","texte":"Transport"},{"id":"lo22mvemyhx902jt3","texte":"Enfants"},{"id":"lo22mvemyhx902jt4","texte":"Prix"}]}'::jsonb, '{"answers":{"lo22mvemyhx902jt1_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt3_lo22mvemyhx902jc1":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc1":"NON","lo22mvemyhx902jt1_lo22mvemyhx902jc2":"NON","lo22mvemyhx902jt2_lo22mvemyhx902jc2":"NON","lo22mvemyhx902jt3_lo22mvemyhx902jc2":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc2":"OUI","lo22mvemyhx902jt1_lo22mvemyhx902jc3":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc3":"OUI","lo22mvemyhx902jt3_lo22mvemyhx902jc3":"NON","lo22mvemyhx902jt4_lo22mvemyhx902jc3":"NON","lo22mvemyhx902jt1_lo22mvemyhx902jc4":"OUI","lo22mvemyhx902jt2_lo22mvemyhx902jc4":"NON","lo22mvemyhx902jt3_lo22mvemyhx902jc4":"OUI","lo22mvemyhx902jt4_lo22mvemyhx902jc4":"OUI"}}'::jsonb, 'Musée des Beaux-Arts: « les salles climatisées » (OUI), « à deux pas de la station de tramway » (OUI), « un livret-jeu permet aux enfants de 6 à 12 ans » (OUI), « les adultes paient 8 € » (NON). Baignade au lac de Vassy: « la plage ne compte aucun arbre » (NON), « n''est desservi par aucune ligne de bus » (NON), « la zone de baignade peu profonde réservée aux plus petits » (OUI), « L''accès à la plage est libre et gratuit pour tous » (OUI). Grottes du Val-Noir: « il fait 13 °C toute l''année » (OUI), « une navette gratuite relie la gare aux grottes » (OUI), « interdite aux enfants de moins de 10 ans » (NON), « 9 € par adulte » (NON). Atelier d''été de la médiathèque: « dans sa grande salle climatisée » (OUI), « prévoyez votre voiture » (NON), « pour les 6-10 ans » (OUI), « L''atelier est gratuit » (OUI).')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemyhx902j' and q.ord = v.ord;
