-- lo22mvemyhx902k
update public.exercises set consigne = '<p>Lisez l''article puis répondez aux questions.</p>', reading_text = '<p><strong>Été 2026 : la France n''a jamais eu aussi chaud</strong></p><p>Le verdict de Météo-France est tombé : l''été 2026 est le plus chaud jamais mesuré en France, devant 2003 et 2022, deux étés qui avaient pourtant marqué les esprits. Juillet a même été le mois le plus chaud depuis le début des relevés, en 1900. Partout dans le pays, des records sont tombés, y compris dans des régions que l''on croyait à l''abri des fortes chaleurs : Strasbourg a ainsi dépassé 40 °C, une première dans l''histoire de la ville.</p><p>La vague de chaleur de la fin juin a été particulièrement violente. Le 25 juin, 72 départements ont été placés en vigilance rouge canicule, une situation jamais vue depuis la création de ce système d''alerte, en 2004. Les écoles ont adapté leurs horaires, et de nombreuses villes ont ouvert des salles rafraîchies pour les personnes âgées. Ces mesures d''urgence, utiles, montrent toutefois les limites d''un pays qui réagit à la crise plus qu''il ne s''y prépare. Adapter des horaires ou ouvrir une salle pendant quelques jours ne transforme ni une ville ni un bâtiment.</p><p>Le bilan humain est lourd. Selon les premières estimations de Santé publique France, plus de 7 300 décès supplémentaires sont liés aux épisodes de chaleur de cet été. L''Île-de-France a été la région la plus touchée, en partie parce que les grandes villes, avec leur béton et leur goudron, gardent la chaleur la nuit. Or c''est justement la nuit que le corps a besoin de récupérer : quand la température ne redescend pas, la fatigue s''accumule de jour en jour, en particulier chez les plus fragiles. Ce constat rappelle que la chaleur n''est pas seulement une question de confort, mais aussi de santé publique.</p><p>À la chaleur s''est ajoutée la sécheresse : jamais les sols n''avaient été aussi secs, et des dizaines de départements ont dû limiter l''usage de l''eau. Pour beaucoup d''experts, cet été n''est pas une exception mais un aperçu de l''avenir. La question n''est donc plus seulement de réduire les émissions de gaz à effet de serre, mais aussi d''adapter nos villes, nos écoles et nos logements à des étés de plus en plus brûlants. Les deux efforts ne s''opposent pas, rappellent-ils : s''adapter sans réduire les émissions reviendrait à courir derrière un problème qui ne cesse de grandir.</p><p><p><small><em>Texte rédigé par FRACILE à partir de : Banque des Territoires, « Canicule, sécheresse, incendies : le bilan climatique hors normes de l''été 2026 » (banquedesterritoires.fr) ; Selectra, « Canicules de l''été 2026 : bilan » (selectra.info) ; données Météo-France et Santé publique France citées par ces articles.</em></small></p></p>' where id = 'lo22mvemyhx902k';
update public.questions q set type = v.type, prompt = v.prompt, payload = v.payload, answer_key = v.answer_key, explanation = v.explanation
from (values
  (1, 'qcm', 'Que nous apprend l''article sur les étés 2003 et 2022 ?', '{"options":["Ils restent aujourd''hui les plus chauds de l''histoire.","Ils ont été moins chauds que celui de 2026.","Ils ont été plus meurtriers que 2026."],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, '« l''été 2026 est le plus chaud jamais mesuré en France, devant 2003 et 2022 ».'),
  (2, 'qcm', 'Pourquoi le record de Strasbourg est-il remarquable ?', '{"options":["Il a été mesuré au début du printemps.","La ville n''avait jamais connu une telle chaleur.","C''est la ville la plus chaude de France."],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, 'Strasbourg vượt 40 °C, « une première dans l''histoire de la ville », ở một vùng « que l''on croyait à l''abri des fortes chaleurs ».'),
  (3, 'vf', 'Le nombre de départements en vigilance rouge le 25 juin n''avait jamais été atteint depuis la création de ce système.', '{"heSo":5}'::jsonb, '{"answer":0,"justification":"une situation jamais vue depuis la création de ce système d''alerte"}'::jsonb, null),
  (4, 'qcm', 'Quelle critique l''auteur fait-il des mesures prises en juin ?', '{"options":["Elles répondent à la crise au lieu de l''anticiper.","Elles ont oublié les personnes âgées des campagnes.","Elles ont été inutiles et coûteuses."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, 'Các biện pháp « utiles », nhưng cho thấy « un pays qui réagit à la crise plus qu''il ne s''y prépare ».'),
  (5, 'qcm', 'Selon les premières estimations, combien de décès supplémentaires sont liés aux chaleurs ?', '{"options":["plus de 7 300","plus de 73 000","environ 730"],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« plus de 7 300 décès supplémentaires sont liés aux épisodes de chaleur ».'),
  (6, 'qcm', 'Pourquoi la chaleur de la nuit est-elle particulièrement dangereuse ?', '{"options":["Les hôpitaux ferment pendant la nuit.","Le corps ne parvient pas à récupérer.","On boit moins d''eau quand on dort."],"heSo":4}'::jsonb, '{"answer":1}'::jsonb, '« c''est justement la nuit que le corps a besoin de récupérer : quand la température ne redescend pas, la fatigue s''accumule ».'),
  (7, 'vf', 'Malgré la chaleur, l''usage de l''eau n''a été limité dans aucun département.', '{"heSo":5}'::jsonb, '{"answer":1,"justification":"des dizaines de départements ont dû limiter l''usage de l''eau"}'::jsonb, null),
  (8, 'qcm', 'Selon les experts, faut-il choisir entre réduire les émissions et s''adapter ?', '{"options":["Non, les deux sont nécessaires.","Oui, il faut d''abord s''adapter.","Oui, réduire les émissions suffit."],"heSo":4}'::jsonb, '{"answer":0}'::jsonb, '« Les deux efforts ne s''opposent pas »: thích nghi mà không giảm phát thải là « courir derrière un problème qui ne cesse de grandir ».')
) as v(ord, type, prompt, payload, answer_key, explanation)
where q.exercise_id = 'lo22mvemyhx902k' and q.ord = v.ord;
delete from public.questions where exercise_id = 'lo22mvemyhx902k' and ord > 8;
